import{z as A,x as B,o as n,c as d,q as E,j as o,D as t,d as a,s as i,S as l,b as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"写合并缓冲","description":"","frontmatter":{"title":"写合并缓冲","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/write-combining.md","filePath":"cs/write-combining.md","lastUpdated":1791063341000}'),C={name:"cs/write-combining.md"};function p(c,e,m,f,D,h){const s=B("Mermaid");return n(),d("div",null,[e[2]||(e[2]=E('<h1 id="写合并缓冲" tabindex="-1">写合并缓冲 <a class="header-anchor" href="#写合并缓冲" aria-label="Permalink to &quot;写合并缓冲&quot;">​</a></h1><div class="epigraph"><p>连续的窄 store 不必每次占一条总线事务；在缓冲里把同一行的字节拼齐，再按整行或扇区写出去。</p><footer>—— 据 Intel 软件开发者手册对 write-combining 的描述；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/line-size-sector">上一课</a> 允许按扇区传输。store 路径上还有更细的东西：图形、DMA、非缓存映射的帧缓冲常常是一串 4–8B 写。若每条都按 <a href="/cs/mesi-protocol">MESI</a> 升级整行，带宽与作废都浪费。本课不重选行大小。缺口是<strong>写合并缓冲（WCB / WC）：在离开核之前把同行字节合并。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>UC 或 WC 内存类型上，store 不进 L1 常规写分配，否则会污染 cache。<a href="/cs/retire-precise-exception">退休</a> 后 store 仍要变成对设备或 DRAM 可见。逐条发 8B 事务，互联效率极差。缺口不是压缩，而是<strong>按物理行地址聚合未完成的 store，掩码记录哪些字节有效，满了或 fence 时一齐发出。</strong></p><p><span class="marginnote">数字实例：往帧缓冲顺序填一屏像素，每像素 4 字节、每条 store 一次窄事务就是几十万次；按 64 字节行合并后，同一行只发一次组合写——事务数砍掉一个数量级，图形填充这类顺序写收益最大。</span></p><p><span class="marginnote">x86 的 WC 内存类型允许写合并与弱序；fence / 串行化指令会冲刷合并缓冲。这是微结构缓冲，也是内存模型可见的宽松点。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>若干项，每项：行地址、字节掩码、数据。退休 store 若地址匹配则并入；否则分配新项或逐出最旧项。逐出：按掩码发写组合事务（或先读-改-写若协议要求）。fence、I/O、过深依赖则 drain。</p><p><span class="marginnote">术语翻译：字节掩码就是「这一行的哪些字节已经有效」的记号——来一个 4 字节 store，就把对应 4 位点亮。逐出时按掩码拼包，有效字节一起走、没写过的字节不碰，所以是「按需拼宽」而不是盲填。</span></p>',10)),(n(),o(l,null,{default:t(()=>[i(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22%E9%80%80%E4%BC%91%E7%9A%84%E7%AA%84%20store%22%5D%20--%3E%20WCB%5B%22%E6%8C%89%E8%A1%8C%E5%90%88%E5%B9%B6%22%5D%0A%20%20WCB%20--%3E%7C%22%E5%90%8C%E8%A1%8C%22%7C%20MERGE%5B%22%E6%9B%B4%E6%96%B0%E6%8E%A9%E7%A0%81%E4%B8%8E%E5%AD%97%E8%8A%82%22%5D%0A%20%20WCB%20--%3E%7C%22%E6%BB%A1%E6%88%96%20fence%22%7C%20OUT%5B%22%E5%8F%91%E5%87%BA%E7%BB%84%E5%90%88%E5%86%99%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r("h2",{id:"机制",tabindex:"-1"},[a("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=r("p",null,[a("对 cacheable 写回内存，常规 SQ + 写分配已经在行内合并；WCB 的主战场是 WC/UC 与某些 streaming store。与 "),r("a",{href:"/cs/lsq-disambiguation"},"LSQ"),a("：转发规则在 WC 区域更弱，程序员不能假设马上被后续 load 看见——这是模型课与 fence 课的接口，本课只要求缓冲在 drain 前可以乱序发出不同行。")],-1)),e[5]||(e[5]=r("p",null,"一个合并条目何时攒、何时被强制排空：",-1)),(n(),o(l,null,{default:t(()=>[i(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22store%20%E5%AD%97%E8%8A%82%20A%EF%BC%8C%E6%96%B0%E8%A1%8C%22%5D%20--%3E%20E%5B%22%E5%88%86%E9%85%8D%E6%9D%A1%E7%9B%AE%EF%BC%9A%E8%A1%8C%E5%9C%B0%E5%9D%80%20%2B%20%E6%8E%A9%E7%A0%81%22%5D%0A%20%20S2%5B%22store%20%E5%AD%97%E8%8A%82%20B%EF%BC%8C%E5%90%8C%E8%A1%8C%22%5D%20--%3E%20E%0A%20%20E%20--%3E%7C%22fence%20%E6%88%96%20I%2FO%20%E6%8C%87%E4%BB%A4%22%7C%20D1%5B%22drain%EF%BC%9A%E6%8C%89%E6%8E%A9%E7%A0%81%E5%8F%91%E7%BB%84%E5%90%88%E5%86%99%22%5D%0A%20%20E%20--%3E%7C%22%E6%9D%A1%E7%9B%AE%E6%94%92%E6%BB%A1%22%7C%20D2%5B%22drain%EF%BC%9A%E6%95%B4%E8%A1%8C%E5%86%99%E5%87%BA%22%5D%0A%20%20E%20--%3E%7C%22%E8%A2%AB%E6%9C%80%E6%97%A7%E9%80%90%E5%87%BA%22%7C%20D3%5B%22drain%EF%BC%9A%E8%AE%A9%E4%BD%8D%E7%BB%99%E6%96%B0%E8%A1%8C%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=E('<p>GPU 的 store buffer / 合并单元更激进，后课合并访存会再遇到「按行拼事务」，先在 CPU 侧把 WCB 钉住。</p><p><span class="marginnote">常见误区：以为 WC 内存上 store 一发出立刻能被读到。合并缓冲让写滞留在核内，别的核与设备都可能晚看见——这正是 fence 存在的理由：需要顺序或即时可见性时，显式 drain 一次。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 DMA 描述符环的驱动写法展开。也不把事务内存的写集合当成 WCB。fence 的代价下一单元末才专讲；这里只承认 drain 是正确性点。TLB 多级是下一课：合并用的是物理行地址，必须已经翻译完。</p><p>后课默认：窄 store 可以在核边合成较宽的写。翻译本身有层次，下一课 TLB 与 PWC。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>写合并把同行窄 store 合成一次事务，主要用于 WC/UC 与流式写。</li><li>fence 与缓冲满会强制 drain。</li><li>多级 TLB 与页表缓存是下一课翻译层次。</li><li>出处：Intel SDM（WC）；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',7))])}const b=A(C,[["render",p]]);export{_ as __pageData,b as default};
